<x-hris.table id="leave-table" endpoint="/leave/data" search filters :columns="[['key'=>'employee.name','label'=>'Employee'],['key'=>'type.name','label'=>'Leave type'],['key'=>'dates_label','label'=>'Inclusive dates'],['key'=>'requested_days','label'=>'Days'],['key'=>'current_status','label'=>'Status']]" :actions="[['name'=>'details','label'=>'Details'],['name'=>'review','label'=>'Review / cancel']]"/>

<x-hris.modal id="leave-modal" title="Apply for leave"><form id="leave-form" data-endpoint="/leave"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none" tabindex="-1"></div><div class="row g-3">
    <x-hris.field name="leave_type_id" label="Leave type" type="select" :options="$types->pluck('name','id')" required/>
    <x-hris.field name="commutation" type="select" :options="['not_requested'=>'Not requested','requested'=>'Requested']" value="not_requested" required/>
    <div class="col-12 d-none" id="leave-detail-wrap"><label for="leave-detail-code" class="form-label">Leave details <span aria-hidden="true">*</span></label><select id="leave-detail-code" name="detail_code" class="form-select"></select></div>
    <div class="col-12 d-none" id="leave-specify-wrap"><label for="leave-details" class="form-label">Specify <span aria-hidden="true">*</span></label><textarea id="leave-details" name="details" class="form-control" rows="2"></textarea></div>
    <div class="col-12 d-none" id="leave-for-disapproval-wrap"><div class="form-check"><input id="leave-for-disapproval" name="for_disapproval" type="checkbox" class="form-check-input"><label for="leave-for-disapproval" class="form-check-label">For Disapproval (Exigency of service)</label></div></div>
    <div class="col-md-6 d-none" id="leave-days-wrap"><label for="leave-days" class="form-label">Number of days <span aria-hidden="true">*</span></label><input id="leave-days" name="requested_days" type="number" class="form-control" min="0.001" max="999" step="0.001"></div>
    <div class="col-12" id="leave-dates-wrap"><fieldset class="border rounded p-3"><legend class="float-none w-auto px-2 h6">Inclusive dates</legend><div class="row g-3 align-items-end"><div class="col-md-5"><label for="leave-date-start" class="form-label">Date or range start</label><input id="leave-date-start" type="date" class="form-control"></div><div class="col-md-5"><label for="leave-date-end" class="form-label">Range end (optional)</label><input id="leave-date-end" type="date" class="form-control"></div><div class="col-md-2"><button id="add-leave-dates" type="button" class="btn btn-outline-primary w-100">Add</button></div></div><div id="selected-leave-dates" class="d-flex flex-wrap gap-2 mt-3" aria-live="polite"><span class="small text-body-secondary">No dates selected.</span></div><p class="form-text mb-0 mt-2">Select one date or an inclusive range. Holidays and schedule-based weekends require confirmation.</p></fieldset></div>
</div></div><div class="modal-footer"><button type="submit" class="btn btn-primary">Submit application</button></div></form></x-hris.modal>

<x-hris.modal id="leave-action" title="Review leave"><form id="leave-action-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none" tabindex="-1"></div><div class="row g-3"><div id="leave-action-wrap" class="col-12"><label for="leave-review-action" class="form-label">Action <span aria-hidden="true">*</span></label><select id="leave-review-action" name="action" class="form-select" required></select></div><div id="leave-no-actions" class="col-12 alert alert-info d-none mb-0">No action is available to you at the application’s current stage.</div><div id="leave-paid-wrap" class="col-md-6 d-none"><x-hris.field name="paid_days" type="number" step="0.001" min="0" class="col-12"/></div><div id="leave-unpaid-wrap" class="col-md-6 d-none"><x-hris.field name="unpaid_days" type="number" step="0.001" min="0" class="col-12"/></div><x-hris.field name="reason" type="textarea" class="col-12"/></div><section class="mt-4" aria-labelledby="leave-history-title"><h3 id="leave-history-title" class="h6">Action history</h3><ol id="leave-action-history" class="list-group"></ol></section></div><div class="modal-footer"><button id="leave-action-submit" type="submit" class="btn btn-primary">Submit decision</button></div></form></x-hris.modal>
@endsection

@push('scripts')<script>
document.addEventListener('hris:ready',()=>{
 const typeCodes=@json($types->mapWithKeys(fn($type)=>[(string)$type->id=>$type->code]));
 const detailOptions={VL:[['1','Within the Philippines'],['2','Abroad (specify)'],['7','Monetization of leave credits'],['8','Terminal Leave']],SL:[['3','In Hospital (specify)'],['4','Out Patient (specify)'],['7','Monetization of leave credits'],['8','Terminal Leave']],SPL:[['1','Within the Philippines'],['2','Abroad (specify)']],STUDY:[['5',"Completion of Master's Degree"],['6','BAR/Board Exam review']]};
 const table=document.querySelector('#leave-table'),form=document.querySelector('#leave-form'),action=document.querySelector('#leave-action-form'),type=form.elements.namedItem('leave_type_id'),detail=form.elements.namedItem('detail_code'),specify=document.querySelector('#leave-specify-wrap'),days=document.querySelector('#leave-days-wrap'),datesWrap=document.querySelector('#leave-dates-wrap'),fl=document.querySelector('#leave-for-disapproval-wrap'),selected=new Set();let acknowledged=false;
 function isMonetization(){return detail.value==='7'}
 function refreshType(){const code=typeCodes[type.value],options=detailOptions[code]||[];detail.replaceChildren(new Option('Choose…',''),...options.map(([value,label])=>new Option(label,value)));document.querySelector('#leave-detail-wrap').classList.toggle('d-none',!options.length);detail.required=options.length>0;fl.classList.toggle('d-none',code!=='FL');if(code!=='FL')form.elements.namedItem('for_disapproval').checked=false;refreshDetail()}
 function refreshDetail(){const needsSpecify=['2','3','4'].includes(detail.value),monetization=isMonetization();specify.classList.toggle('d-none',!needsSpecify);form.elements.namedItem('details').required=needsSpecify;if(!needsSpecify)form.elements.namedItem('details').value='';days.classList.toggle('d-none',!monetization);form.elements.namedItem('requested_days').required=monetization;datesWrap.classList.toggle('d-none',monetization);if(monetization){selected.clear();renderDates()}}
 function iso(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
 function range(start,end){const result=[],cursor=new Date(`${start}T00:00:00`),last=new Date(`${end||start}T00:00:00`);while(cursor<=last&&result.length<60){result.push(iso(cursor));cursor.setDate(cursor.getDate()+1)}return result}
 function renderDates(){const box=document.querySelector('#selected-leave-dates');box.replaceChildren();if(!selected.size){const empty=document.createElement('span');empty.className='small text-body-secondary';empty.textContent='No dates selected.';box.append(empty);return}[...selected].sort().forEach(date=>{const button=document.createElement('button');button.type='button';button.className='btn btn-sm btn-outline-secondary';button.textContent=`${date} ×`;button.setAttribute('aria-label',`Remove ${date}`);button.onclick=()=>{selected.delete(date);renderDates()};box.append(button)})}
 type.addEventListener('change',refreshType);detail.addEventListener('change',refreshDetail);refreshType();
 document.querySelector('#add-leave-dates').onclick=async()=>{const start=document.querySelector('#leave-date-start').value,end=document.querySelector('#leave-date-end').value;if(!start)return HRIS.feedback('Choose a date first.',true);if(end&&end<start)return HRIS.feedback('Range end must be on or after the start.',true);const values=range(start,end);if(values.length>=60&&end&&values.at(-1)!==end)return HRIS.feedback('Select at most 60 inclusive dates.',true);try{const result=await HRIS.request('/leave/date-check',{method:'POST',body:{dates:values}});if(result.warnings.length){const summary=result.warnings.map(item=>`${item.date}: ${item.reason}`).join('\n');if(!await HRIS.confirm(`The following dates are holidays or non-working days:\n\n${summary}\n\nAdd them anyway?`))return;acknowledged=true}values.forEach(date=>selected.add(date));renderDates()}catch(error){HRIS.feedback(error.message,true)}};
 HRIS.bindForm(form,{prepare:body=>{body.dates=isMonetization()?[]:[...selected].sort().map(date=>({date}));body.acknowledge_non_working_days=acknowledged;body.for_disapproval=form.elements.namedItem('for_disapproval').checked},success:()=>{selected.clear();acknowledged=false;renderDates();table.table.load()}});
 const reviewAction=action.elements.namedItem('action'),reason=action.elements.namedItem('reason'),submitDecision=document.querySelector('#leave-action-submit');
 function refreshDecisionFields(){const finalApproval=['approve_ed','witness'].includes(reviewAction.value),needsReason=['return','reject_dc','reject_ed','reject_witness'].includes(reviewAction.value);document.querySelector('#leave-paid-wrap').classList.toggle('d-none',!finalApproval);document.querySelector('#leave-unpaid-wrap').classList.toggle('d-none',!finalApproval);reason.required=needsReason}
 function renderHistory(history){const list=document.querySelector('#leave-action-history');list.replaceChildren();history.forEach(item=>{const entry=document.createElement('li');entry.className='list-group-item';const heading=document.createElement('div');heading.className='d-flex flex-wrap justify-content-between gap-2';const status=document.createElement('strong');status.textContent=item.status;const time=document.createElement('span');time.className='small text-body-secondary';time.textContent=item.acted_at;heading.append(status,time);const actor=document.createElement('div');actor.className='small';actor.textContent=`${item.actor} · ${(item.actor_role||'').replaceAll('_',' ')}`;entry.append(heading,actor);if(item.reason){const note=document.createElement('p');note.className='mb-0 mt-2';note.textContent=item.reason;entry.append(note)}list.append(entry)});if(!history.length){const empty=document.createElement('li');empty.className='list-group-item text-body-secondary';empty.textContent='No recorded actions.';list.append(empty)}}
 reviewAction.addEventListener('change',refreshDecisionFields);
 HRIS.bindForm(action,{success:()=>table.table.load()});table.addEventListener('table:action',({detail:{action:kind,row}})=>{if(kind==='details')HRIS.showDetails('Leave application',row);else{HRIS.fillForm(action,{paid_days:row.requested_days,unpaid_days:0});const options=Object.entries(row.available_actions||{});reviewAction.replaceChildren(new Option('Choose…',''),...options.map(([value,label])=>new Option(label,value)));document.querySelector('#leave-action-wrap').classList.toggle('d-none',!options.length);document.querySelector('#leave-no-actions').classList.toggle('d-none',options.length>0);submitDecision.classList.toggle('d-none',!options.length);reviewAction.required=options.length>0;renderHistory(row.action_history||[]);refreshDecisionFields();action.dataset.endpoint=`/leave/${row.id}/transition`;HRIS.openModal('leave-action')}})
});
</script>@endpush
